  const candidate={base:patchBase(original.base),executor:patchExecutor(original.executor),plugin:patchPlugin(original.plugin),policy:patchPolicy(original.policy),v4helper:null};const pluginSha=shaBuffer(Buffer.from(candidate.plugin));candidate.v4helper=patchV4Helper(original.v4helper,pluginSha);
  syntaxCheck(FILES.base,candidate.base,false);syntaxCheck(FILES.executor,candidate.executor,false);syntaxCheck(FILES.plugin,candidate.plugin,true);JSON.parse(candidate.policy);syntaxCheck(FILES.v4helper,candidate.v4helper,false);syntaxCheck(FILES.helper,HELPER_CONTENT,false);
  const helperTmp='/tmp/prhm-v6-selftest-preflight-'+process.pid+'.js';fs.writeFileSync(helperTmp,HELPER_CONTENT,{mode:0o700});let helperPreflight;try{const r=exec(NODE,[helperTmp,'--preflight-only'],{timeout:90000});helperPreflight=JSON.parse(String(r.stdout||'{}').trim());}finally{try{fs.unlinkSync(helperTmp)}catch{}}
