  for(const key of ['base','executor','plugin','policy','v4helper']){const dst=path.join(backupDir,key+'-'+path.basename(FILES[key])+'.bak');fs.copyFileSync(FILES[key],dst,fs.constants.COPYFILE_EXCL);fs.chmodSync(dst,0o600);}
